    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                    pairs.append((color, r, c, dr, dc))
    for color, r, c, dr, dc in pairs:
        # Extend away from each end of each equal-color diagonal pair.
        for sr, sc, step_r, step_c in ((r, c, -dr, -dc),
                                       (r + dr, c + dc, dr, dc)):
            rr, cc = sr + step_r, sc + step_c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                out[rr][cc] = color
                rr += step_r
                cc += step_c
    return out
